`timescale 1ns/1ps
//==============================================================================
// tb_Ascon_top : self-checking testbench for the Ascon-AEAD128 core
//------------------------------------------------------------------------------
// Vectors
//   1 .. 1089 : official Ascon-AEAD128 known-answer tests (file
//               LWC_AEAD_KAT_128_128.txt of github.com/ascon/ascon-c,
//               crypto_aead/asconaead128). PT 0..32 bytes x AD 0..32 bytes.
//   next 211  : random key, nonce, AD (0..64 bytes), PT (0..64 bytes). Expected
//               values from the pyascon reference model ("Ascon-AEAD128").
// Each vector runs three tests:
//   A) encrypt            : every ciphertext beat and the tag are compared
//   B) decrypt, good tag  : every plaintext beat is compared, tag_match must be 1
//   C) decrypt, bad tag   : one tag bit is flipped, tag_match must be 0
//
// Byte order: byte i of every field is bits [8*i +: 8] (little-endian).
// Unused bytes of a short beat are driven with FF to prove that the core
// masks them.
// Result line at the end:  "RESULT: PASS ..."  or  "RESULT: FAIL ...".
//==============================================================================
module tb_Ascon_top;

reg clk = 0;  always #0.993 clk = ~clk;
reg rst = 1;
reg [127:0] data_in = 0;
reg [4:0]   data_len = 0;
reg         data_valid = 0, mode = 0;
wire [127:0] data_out;
wire data_out_valid, data_ready, tag_match;

Ascon_top dut (
    .clk(clk), .rst(rst), .data_in(data_in), .data_len(data_len),
    .data_valid(data_valid), .mode(mode),
    .data_out(data_out), .data_out_valid(data_out_valid),
    .data_ready(data_ready), .tag_match(tag_match));

// output capture
reg [127:0] outq [0:7];
reg         tm;
integer nout = 0, errors = 0, tests = 0, vectors = 0;
always @(posedge clk) if (data_out_valid) begin
    if (nout < 8) outq[nout] = data_out;
    tm   = tag_match;
    nout = nout + 1;
end

// one beat: wait for data_ready, hold data for one clock
task beat(input [127:0] d, input [4:0] len);
begin
    @(negedge clk); while (!data_ready) @(negedge clk);
    data_in = d; data_len = len; data_valid = 1;
    @(negedge clk); data_valid = 0; data_len = 0; data_in = 0;
end
endtask

task idle; begin @(negedge clk); while (!data_ready) @(negedge clk); end endtask

// send a byte stream: full 16-byte beats, then one last beat of 0..15 bytes
task send_stream(input [511:0] d, input integer len);
integer rem;
reg [511:0] sh;
reg [127:0] junk;
begin
    rem = len; sh = d;
    while (rem >= 16) begin
        beat(sh[127:0], 5'd16);
        sh = sh >> 128; rem = rem - 16;
    end
    junk = {128{1'b1}} << (8 * rem);            // FF in all unused bytes
    beat(sh[127:0] | junk, rem[4:0]);
end
endtask

// compare captured data beats (index 0 ..) with an expected byte stream
task check_stream(input integer id, input [511:0] exp, input integer len, input [8*3:1] name);
integer k, nb;
reg [511:0] sh;
begin
    nb = len / 16 + 1; sh = exp;
    for (k = 0; k < nb; k = k + 1) begin
        if (outq[k] !== sh[127:0]) begin
            errors = errors + 1;
            $display("FAIL vec %0d %0s beat %0d: got %h exp %h", id, name, k, outq[k], sh[127:0]);
        end
        sh = sh >> 128;
    end
end
endtask

task run(input integer id, input integer adlen, input integer ptlen,
         input [127:0] key, input [127:0] nonce,
         input [511:0] ad, input [511:0] pt, input [511:0] ct, input [127:0] tag);
integer nb, e0;
begin
    nb = ptlen / 16 + 1;          // number of text beats
    e0 = errors;

    // ---------------- A) encrypt ----------------
    mode = 0; nout = 0;
    beat(key, 5'd16); beat(nonce, 5'd16);
    send_stream(ad, adlen);
    send_stream(pt, ptlen);
    idle;
    check_stream(id, ct, ptlen, "CT ");
    if (nout !== nb + 1) begin errors = errors + 1; $display("FAIL vec %0d enc: %0d output beats, exp %0d", id, nout, nb + 1); end
    if (outq[nb] !== tag) begin errors = errors + 1; $display("FAIL vec %0d TAG: got %h exp %h", id, outq[nb], tag); end
    tests = tests + 1;

    // ---------------- B) decrypt, good tag ----------------
    mode = 1; nout = 0; tm = 1'bx;
    beat(key, 5'd16); beat(nonce, 5'd16);
    send_stream(ad, adlen);
    send_stream(ct, ptlen);
    beat(tag, 5'd16);
    check_stream(id, pt, ptlen, "PT ");
    if (nout !== nb + 1) begin errors = errors + 1; $display("FAIL vec %0d dec: %0d output beats, exp %0d", id, nout, nb + 1); end
    if (tm !== 1'b1) begin errors = errors + 1; $display("FAIL vec %0d dec: tag_match = %b, exp 1", id, tm); end
    tests = tests + 1;

    // ---------------- C) decrypt, bad tag ----------------
    nout = 0; tm = 1'bx;
    beat(key, 5'd16); beat(nonce, 5'd16);
    send_stream(ad, adlen);
    send_stream(ct, ptlen);
    beat(tag ^ (128'd1 << (id % 128)), 5'd16);
    if (tm !== 1'b0) begin errors = errors + 1; $display("FAIL vec %0d bad tag: tag_match = %b, exp 0", id, tm); end
    tests = tests + 1;
    mode = 0;

    vectors = vectors + 1;
    if (errors != e0) $display("vec %0d (AD %0d bytes, PT %0d bytes) FAILED", id, adlen, ptlen);
end
endtask

